import{_ as n,o as e,c as a,a5 as t}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"63. File Descriptors and open/read/write","description":"The Little Book of C — 63. File Descriptors and open/read/write","frontmatter":{"title":"63. File Descriptors and open/read/write","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Working Close to the System"],"description":"The Little Book of C — 63. File Descriptors and open/read/write","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":63,"sidebarWeight":63,"lang":"en-US","alternateEn":"/posts/c教程/en-US/07-Working Close to the System/063-File Descriptors and openreadwrite","alternateZh":"/posts/c教程/zh-CN/07-贴近系统/063-File Descriptors and openreadwrite"},"headers":[],"relativePath":"posts/c教程/en-US/07-Working Close to the System/063-File Descriptors and openreadwrite.md","filePath":"posts/c教程/en-US/07-Working Close to the System/063-File Descriptors and openreadwrite.md","lastUpdated":1790163617000}'),p={name:"posts/c教程/en-US/07-Working Close to the System/063-File Descriptors and openreadwrite.md"};function i(l,s,o,d,c,r){return e(),a("div",null,[...s[0]||(s[0]=[t(`<p>[中文版本](/posts/c教程/zh-CN/07-贴近系统/063-File Descriptors and openreadwrite)</p><p>Now that you can create and manage processes, let’s explore how those processes communicate with files, devices, and even each other, through file descriptors.</p><p>File descriptors (FDs) are one of the simplest yet most powerful abstractions in Unix and C. Everything, files, pipes, sockets, terminals, is represented by a small integer handle. Once you understand how to open, read, write, and close file descriptors, you can interact with any I/O system on a Unix machine.</p><h4 id="step-1-what-is-a-file-descriptor" tabindex="-1">Step 1. What Is a File Descriptor? <a class="header-anchor" href="#step-1-what-is-a-file-descriptor" aria-label="Permalink to &quot;Step 1. What Is a File Descriptor?&quot;">​</a></h4><p>A file descriptor is an integer that identifies an open resource in your process. Every process starts with three open descriptors by default:</p><table tabindex="0"><thead><tr><th>FD</th><th>Symbolic Name</th><th>Description</th></tr></thead><tbody><tr><td>0</td><td><code>STDIN_FILENO</code></td><td>Standard input (keyboard)</td></tr><tr><td>1</td><td><code>STDOUT_FILENO</code></td><td>Standard output (screen)</td></tr><tr><td>2</td><td><code>STDERR_FILENO</code></td><td>Standard error (screen)</td></tr></tbody></table><p>Each time you open a file, socket, or pipe, the kernel gives you the lowest unused FD.</p><h4 id="step-2-opening-files-with-open" tabindex="-1">Step 2. Opening Files with open() <a class="header-anchor" href="#step-2-opening-files-with-open" aria-label="Permalink to &quot;Step 2. Opening Files with open()&quot;">​</a></h4><p>You can open files directly using the system call layer, instead of<code>fopen()</code> from stdio.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;fcntl.h&gt;</span><span>     // open</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span><span>    // close, read, write</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span><span>     // perror</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;data.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    if (fd == -1) {</span></span>
<span class="line"><span>        perror(&quot;open failed&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    printf(&quot;File descriptor: %d\\n&quot;, fd);</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc open_demo.c -o open_demo</span></span>
<span class="line"><span>./open_demo</span></span></code></pre></div><p>Output example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>File descriptor: 3</span></span></code></pre></div><h4 id="step-3-reading-from-a-file" tabindex="-1">Step 3. Reading from a File <a class="header-anchor" href="#step-3-reading-from-a-file" aria-label="Permalink to &quot;Step 3. Reading from a File&quot;">​</a></h4><p><code>read(fd, buffer, size)</code> reads raw bytes into a memory buffer.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;data.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    if (fd == -1) return 1;</span></span>
<span class="line"><span>    char buf[64];</span></span>
<span class="line"><span>    ssize_t n = read(fd, buf, sizeof(buf) - 1);</span></span>
<span class="line"><span>    if (n &gt; 0) {</span></span>
<span class="line"><span>        buf[n] = &#39;\\0&#39;;</span></span>
<span class="line"><span>        printf(&quot;Read %zd bytes: %s\\n&quot;, n, buf);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read 12 bytes: Hello world</span></span></code></pre></div><h4 id="step-4-writing-to-a-file" tabindex="-1">Step 4. Writing to a File <a class="header-anchor" href="#step-4-writing-to-a-file" aria-label="Permalink to &quot;Step 4. Writing to a File&quot;">​</a></h4><p><code>write(fd, buffer, size)</code> writes raw bytes from memory to a file descriptor.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;out.txt&quot;, O_WRONLY | O_CREAT | O_TRUNC, 0644);</span></span>
<span class="line"><span>    const char msg[] = &quot;Writing from C using write()\\n&quot;;</span></span>
<span class="line"><span>    write(fd, msg, strlen(msg));</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>This overwrites<code>out.txt</code> with your message. Flags:</p><ul><li><code>O_WRONLY</code>→ write-only</li><li><code>O_CREAT</code>→ create if it doesn’t exist</li><li><code>O_TRUNC</code>→ truncate (clear) existing contents</li></ul><p>The final argument<code>0644</code> sets Unix permissions:</p><ul><li>Owner can read/write,</li><li>Group/others can read.</li></ul><h4 id="step-5-append-and-non-blocking-modes" tabindex="-1">Step 5. Append and Non-blocking Modes <a class="header-anchor" href="#step-5-append-and-non-blocking-modes" aria-label="Permalink to &quot;Step 5. Append and Non-blocking Modes&quot;">​</a></h4><p>You can combine flags using bitwise OR:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int fd = open(&quot;log.txt&quot;, O_WRONLY | O_CREAT | O_APPEND, 0644);</span></span></code></pre></div><p><code>O_APPEND</code> moves the file offset to the end before every write, ideal for logs.</p><p>You can also open files as non-blocking:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int fd = open(&quot;pipe&quot;, O_RDONLY | O_NONBLOCK);</span></span></code></pre></div><p>Useful for I/O on sockets or named pipes.</p><h4 id="step-6-duplicating-descriptors" tabindex="-1">Step 6. Duplicating Descriptors <a class="header-anchor" href="#step-6-duplicating-descriptors" aria-label="Permalink to &quot;Step 6. Duplicating Descriptors&quot;">​</a></h4><p>You can duplicate an FD using<code>dup()</code> or<code>dup2()</code>. This is how redirection works (<code>&gt;</code> in shells).</p><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;output.txt&quot;, O_WRONLY | O_CREAT | O_TRUNC, 0644);</span></span>
<span class="line"><span>    dup2(fd, STDOUT_FILENO);  // redirect stdout to file</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>    printf(&quot;This goes into output.txt!\\n&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>After<code>dup2</code>, everything printed to stdout goes to<code>output.txt</code>.</p><p>Run and inspect:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./redir_demo</span></span>
<span class="line"><span>cat output.txt</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>This goes into output.txt!</span></span></code></pre></div><h4 id="step-7-offsets-and-lseek" tabindex="-1">Step 7. Offsets and lseek() <a class="header-anchor" href="#step-7-offsets-and-lseek" aria-label="Permalink to &quot;Step 7. Offsets and lseek()&quot;">​</a></h4><p>You can move around inside a file using<code>lseek(fd, offset, whence)</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;data.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    lseek(fd, 5, SEEK_SET); // move to byte 5</span></span>
<span class="line"><span>    char buf[16];</span></span>
<span class="line"><span>    read(fd, buf, 10);</span></span>
<span class="line"><span>    buf[10] = &#39;\\0&#39;;</span></span>
<span class="line"><span>    printf(&quot;Chunk: %s\\n&quot;, buf);</span></span>
<span class="line"><span>    close(fd);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><code>whence</code> can be:</p><ul><li><code>SEEK_SET</code>(from start)</li><li><code>SEEK_CUR</code>(from current)</li><li><code>SEEK_END</code>(from end)</li></ul><h4 id="step-8-error-checking-and-return-values" tabindex="-1">Step 8. Error Checking and Return Values <a class="header-anchor" href="#step-8-error-checking-and-return-values" aria-label="Permalink to &quot;Step 8. Error Checking and Return Values&quot;">​</a></h4><p>All system calls return:</p><ul><li>A nonnegative value → success</li><li><code>-1</code>→ error (check<code>errno</code>)</li></ul><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;errno.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int fd = open(&quot;missing.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    if (fd == -1)</span></span>
<span class="line"><span>        fprintf(stderr, &quot;Error: %s\\n&quot;, strerror(errno));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: No such file or directory</span></span></code></pre></div><h4 id="tiny-code-copy-file-using-system-calls" tabindex="-1">Tiny Code: Copy File Using System Calls <a class="header-anchor" href="#tiny-code-copy-file-using-system-calls" aria-label="Permalink to &quot;Tiny Code: Copy File Using System Calls&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;fcntl.h&gt;</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int src = open(&quot;source.txt&quot;, O_RDONLY);</span></span>
<span class="line"><span>    int dst = open(&quot;copy.txt&quot;, O_WRONLY | O_CREAT | O_TRUNC, 0644);</span></span>
<span class="line"><span>    if (src == -1 || dst == -1) {</span></span>
<span class="line"><span>        perror(&quot;open failed&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    char buf[256];</span></span>
<span class="line"><span>    ssize_t n;</span></span>
<span class="line"><span>    while ((n = read(src, buf, sizeof(buf))) &gt; 0)</span></span>
<span class="line"><span>        write(dst, buf, n);</span></span>
<span class="line"><span>    close(src);</span></span>
<span class="line"><span>    close(dst);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Compile and run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc copy.c -o copy</span></span>
<span class="line"><span>./copy</span></span></code></pre></div><p>Now<code>copy.txt</code> is identical to<code>source.txt</code>, using pure syscalls.</p><h4 id="step-9-reading-from-stdin-and-writing-to-stdout" tabindex="-1">Step 9. Reading from STDIN and Writing to STDOUT <a class="header-anchor" href="#step-9-reading-from-stdin-and-writing-to-stdout" aria-label="Permalink to &quot;Step 9. Reading from STDIN and Writing to STDOUT&quot;">​</a></h4><p>You can use<code>read(0, ...)</code> and<code>write(1, ...)</code> directly for console I/O.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    char buf[64];</span></span>
<span class="line"><span>    ssize_t n = read(STDIN_FILENO, buf, sizeof(buf));</span></span>
<span class="line"><span>    write(STDOUT_FILENO, buf, n);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Run:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./echo_demo</span></span>
<span class="line"><span>hello world</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello world</span></span></code></pre></div><p>That’s the essence of every shell command.</p><h4 id="step-10-why-it-matters" tabindex="-1">Step 10. Why It Matters <a class="header-anchor" href="#step-10-why-it-matters" aria-label="Permalink to &quot;Step 10. Why It Matters&quot;">​</a></h4><p>File descriptors unify I/O across everything:</p><ul><li>Regular files</li><li>Pipes and sockets</li><li>Devices and terminals</li></ul><p>They let you control exactly how data flows in and out of your program, a foundation for system tools, servers, and OS-level programming.</p><p>Once you understand these primitives, you can build your own versions of tools like<code>cat</code>,<code>tee</code>, and even simple shells.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><ol><li>Write a mini<code>cat</code> clone using<code>read()</code> and<code>write()</code>.</li><li>Use<code>dup2()</code> to redirect both stdout and stderr to a file.</li><li>Add error messages using<code>perror()</code> and handle<code>EINTR</code>.</li><li>Use<code>lseek()</code> to skip the first N bytes of a file before printing.</li><li>Implement a simple file appender with<code>O_APPEND</code>.</li></ol><p>Next, you’ll use these file descriptors to make processes communicate, building pipes and redirection, the same mechanisms shells use to connect commands like<code>ls | grep</code>.</p>`,75)])])}const g=n(p,[["render",i]]);export{h as __pageData,g as default};
